from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Affection Heart":"Heart card represents care; affection can be words, time, help, or consented touch.","Bashful Bunny":"Character suggests bashfulness; it is a discussion cue, not a diagnosis.","Calm Cloud":"Calm metaphor; nobody must feel calm on command.","Disappointed Face":"Disappointment cue; a face alone cannot prove another person's feeling.","Excited Eyes":"Excitement cue; wide eyes have many meanings, so ask rather than assume.","Friendship Bracelet":"Friendship symbol; exchanging one is optional and does not measure friendship quality.","Gentle Hands":"Cue for safe hands; gentleness includes respecting space and permission.","Happy Face":"Happiness cue; people show happiness differently and smiles have many meanings.","Inside Voice":"Cue for quieter indoor volume; feelings and needs can still be said.","Jealous Face":"Jealousy cue; having the feeling is different from acting harmfully.","Kind Hands":"Cue for safe helpful hands; kindness also includes words, listening, boundaries, or help.","Love Letter":"Written care message; respect privacy and recipient comfort.","Mad Face":"Anger cue; the feeling is normal while unsafe actions still need limits.","Note of Thanks":"Written appreciation; gratitude works best when genuine, not forced.","Optimism Sun":"Hopeful metaphor; optimism does not promise problems disappear.","Proud Star":"Pride symbol for effort, growth, identity, or achievement; no comparison is required.","Question Card":"Prompt to ask, clarify, or check when feelings or intentions are uncertain.","Relaxation Pillow":"Comfort object for rest/pause; it cannot guarantee relaxation or block breathing.","Sharing Box":"Turn-taking container; sharing respects ownership, safety, and boundaries.","Thank-you Card":"Written gratitude; appreciation works best when specific and sincere.","Understanding Heart":"Symbol for perspective-taking; understanding does not require agreement or accepting harm.","Voice Card":"Prompt to communicate needs, feelings, questions, or boundaries.","Worry Box":"Optional worry-note activity; it does not erase worry or replace needed support.","XOXO Card":"X/O affection symbols in some cultures; physical affection always requires consent.","Yoga Card":"Optional comfortable movement/breathing prompt; range stays pain-free.","Zigzag Breath Card":"Visual breathing pace; return to normal breathing if uncomfortable or dizzy.","Angry Face":"Anger cue; one face cannot show the whole reason or intensity.","Brave Badge":"Courage symbol; bravery can include asking help, speaking up, or declining unsafe risk.","Emotion Cards":"Cards help name/discuss feelings; they are vocabulary tools, not emotion tests.","Feelings Wheel":"Chart groups emotion words for reflection; categories are not fixed scientific boxes.","Gratitude Jar":"Optional gratitude notes can record appreciated moments without dismissing difficult feelings.","Interest Card":"Prompt represents curiosity or engagement; interest can change by activity, time, and person.","Joy Jar":"Joy notes recall enjoyable moments without requiring constant happiness.","Kindness Card":"Prompt for considerate action; kindness includes respecting another person's no.","Lonely Face":"Loneliness cue; someone can feel lonely even around others.","Mood Meter":"Self-reflection chart for feeling/energy; not a diagnosis.","Okay Sign":"Okay symbol varies by culture; verbal confirmation can be clearer.","Patience Timer":"Timer makes waiting visible; frustration need not vanish.","Respect Badge":"Respect symbol; boundaries, listening, fairness, and safety matter more than obedience.","Upset Face":"Upset cue; ask what is happening instead of guessing from a face.","Valued Badge":"Reminder that a person matters; worth is not earned by winning or cheerfulness.","Xylophone Calm Toy":"Soft music toy may settle some people; others may prefer quiet.","Caring Card":"Prompt to check needs or offer help; ask before touching or solving.","Delight Star":"Delight symbol; the feeling is possible, never required.","Heart":"Care/love symbol here, not the biological heart.","Nervous Face":"Nervousness cue; a face alone cannot measure experience.","Quiet Corner":"Optional low-stimulation pause space; not punishment or forced isolation.","Tired Face":"Tiredness cue; many causes are possible and rest/support may help.","Warm Hug Card":"Hug prompt only when both want it; care never requires touch.","Yellow Feelings Chart":"Color-coded feelings chart; yellow only means what this chart key defines.","Zen Cushion":"Seated quiet-practice cushion; comfort is individual and Zen is not a generic calm-down command.",
"Smile":"Smile can express many social/emotional states; it does not prove happiness or need to be demanded.",}
ACTIONS={"Warm Hug Card":"Cross arms over your own shoulders or ask-consent gesture—no touching another person.","XOXO Card":"Point to X/O symbols; no kiss/hug mime toward another person.","Yoga Card":"Show one comfortable neutral pose; no forced stretch.","Zigzag Breath Card":"Trace zigzag slowly; breathe normally if pacing feels uncomfortable.","Quiet Corner":"Point to a quiet-space picture; never mime sending someone away.","Worry Box":"Pretend place a paper note in a box; say worries can still be shared with a trusted adult.","Xylophone Calm Toy":"Tap two fingertips softly; sound is optional.","Inside Voice":"Lower volume slightly for one word; do not whisper needs away.","Okay Sign":"Point to the card rather than relying on the hand gesture.","Sharing Box":"Pretend offer then pause for the other person's choice.","Kind Hands":"Keep hands on your own body or open palms; no touching others.","Gentle Hands":"Keep hands on your own body or open palms; no touching others."}
